      \u0275\u0275advance(6);
      \u0275\u0275classProp("active", ctx.selectedProduction() === "solaire");
      \u0275\u0275advance(9);
      \u0275\u0275classProp("active", ctx.isDetailActive("get_weather_data"));
      \u0275\u0275advance(7);
      \u0275\u0275classProp("active", ctx.isDetailActive("calculate_solar_parameters"));
      \u0275\u0275advance(23);
      \u0275\u0275classProp("active", ctx.isDetailActive("convert_solar"));
      \u0275\u0275advance(11);
