    const nodeLabels = [
      "Gaz",
      "\xC9lectricit\xE9",
      "Transport",
      "B\xE2timent",
      "Industrie",
      "Hydro",
      "Solaire",
      "\xC9olien",
      "Thermique",
      "Nucl\xE9aire"
    ];
    const colorMap = {
      Gaz: "#a9a9a9",
      \u00C9lectricit\u00E9: "#34c759",
      Transport: "#ff7f50",
      B\u00E2timent: "#20b2aa",
      Industrie: "#778899",
      Hydro: "#1e90ff",
      Solaire: "#ffd700",
      \u00C9olien: "#87ceeb",
      Thermique: "#ff8c00",
      Nucl\u00E9aire: "#9370db"
    };
    const nodeIndex = {
      Gaz: 0,
      \u00C9lectricit\u00E9: 1,
      Transport: 2,
      B\u00E2timent: 3,
      Industrie: 4,
      Hydro: 5,
      Solaire: 6,
      \u00C9olien: 7,
      Thermique: 8,
      Nucl\u00E9aire: 9
    };
    this.consumption.forEach((row) => {
      const [_, __, ___, secteur, energie, val] = row;
      if (secteur in nodeIndex && energie in nodeIndex) {
        source.push(nodeIndex[energie]);
        target.push(nodeIndex[secteur]);
        value.push(parseFloat(val));
        labels.push(`${energie} \u2192 ${secteur}: ${val} TWh`);
      }
    });
    this.production.forEach((row) => {
      const [_, __, ___, cible, sourceProd, val] = row;
      if (sourceProd in nodeIndex && cible in nodeIndex) {
        source.push(nodeIndex[sourceProd]);
        target.push(nodeIndex[cible]);
        value.push(parseFloat(val));
        labels.push(`${sourceProd} \u2192 ${cible}: ${val} TWh`);
      }
    });
